{
  "identity": {
    "name": "Treasure Valley IT",
    "location": "9019 W Barnes St, Boise, ID 83709",
    "claims": [
      {
        "statement": "The business operates under the name Treasure Valley IT (also referred to as TVIT).",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "At Treasure Valley IT, our mission is to deliver exceptional service by dedicating our full attention to each client's unique needs."
      },
      {
        "statement": "Treasure Valley IT's main office is located at 9019 W Barnes St, Boise, ID 83709.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "Main Office: 9019 W Barnes St Boise ID 83709"
      },
      {
        "statement": "The company serves Boise, Idaho and surrounding Treasure Valley communities including Eagle, Kuna, Nampa, Garden City, Middleton, Meridian, Star, and Caldwell.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We are proud to serve Boise, Idaho and the surrounding areas, including: Boise Eagle Kuna Nampa Garden City Middleton Meridian Star Caldwell Idaho"
      }
    ]
  },
  "industry": {
    "industry": "Information Technology Services / Managed Service Provider (MSP)",
    "activities": [
      "Managed IT and co-managed IT services",
      "Core IT infrastructure, server repair, network management, and disaster recovery",
      "Cybersecurity, IT compliance, and audit services",
      "Software and productivity services (Microsoft Office 365, email migration, IT project management, hardware procurement)",
      "Commercial and residential IT support"
    ],
    "claims": [
      {
        "statement": "Treasure Valley IT provides IT services to both business and residential clients.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We provide comprehensive IT services for both businesses and residential clients."
      },
      {
        "statement": "The company offers both fully managed IT services and co-managed IT across multiple support tiers.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We offer fully managed IT services as well as co-managed IT with different tiers of support."
      },
      {
        "statement": "Its core infrastructure offerings include managed IT, disaster recovery, server repair, cybersecurity, and network management.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/our-services/",
        "quote": "Managed IT, disaster recovery, server repair, cybersecurity, network management, and more."
      },
      {
        "statement": "The company is an IT managed service provider rather than a home-service trade contractor in HVAC, plumbing, or electrical.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/our-services/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.tvit.net/",
    "claims": [
      {
        "statement": "The website offers free network assessments to prospective business clients.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "We’ll assess your network, identify risks, and recommend solutions—all at no cost."
      },
      {
        "statement": "Treasure Valley IT states that it is a member of the Idaho Veterans Chamber of Commerce and employs veterans on its team.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/about/",
        "quote": "At Treasure Valley IT, we are honored to be proud members of the Idaho Veterans Chamber of Commerce"
      },
      {
        "statement": "The website lists Dell Technologies, Verizon One Talk, Acronis, Apple, MailProtector, Microsoft, Lenovo, and Fortinet under its vendors section.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/",
        "quote": "Our Vendors Dell Technologies Verizon One Talk Acronis Apple MailProtector Microsoft Lenovo Fortinet"
      },
      {
        "statement": "The company applies a 3.5% processing fee to online credit card bill payments.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/client-support/pay-bill/",
        "quote": "*Please note that a 3.5% credit card processing fee will be applied at checkout."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company states that it provides Microsoft Certified Support.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/software-and-productivity-services/",
        "quote": "Certified support for Microsoft products, including troubleshooting, updates, and integration."
      },
      {
        "statement": "The company states that it provides Apple-certified support.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/software-and-productivity-services/",
        "quote": "Reliable Apple-certified support for iOS and iOS X."
      }
    ],
    "limitations": "No state business-registration numbers, corporate entity filings, or trade contractor license numbers were published on the pages read."
  },
  "existingSoftware": [
    {
      "product": "Google Ads",
      "purpose": "Advertising and remarketing cookies",
      "evidence": {
        "statement": "The privacy policy states that Google is used as a third-party vendor to serve ads using cookies.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/privacy-policy/",
        "quote": "Google, as a third party vendor, uses cookies to serve ads."
      }
    },
    {
      "product": "Gravatar (automattic.com)",
      "purpose": "Commenter profile image lookup on website",
      "evidence": {
        "statement": "The privacy policy states that an anonymized hash of a commenter's email address may be sent to the Gravatar service.",
        "label": "fact",
        "sourceUrl": "https://www.tvit.net/privacy-policy/",
        "quote": "An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service"
      }
    },
    {
      "product": "Client Portal hosted at tvit.itclientportal.com",
      "purpose": "Customer support portal login",
      "evidence": {
        "statement": "The Client Portal page references the external host tvit.itclientportal.com for client logins.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/client-support/client-portal/",
        "quote": null
      }
    },
    {
      "product": "Payment Portal hosted at secure2.wise-sync.com",
      "purpose": "Online invoice and bill payment processing",
      "evidence": {
        "statement": "The Pay Bill page references the external host secure2.wise-sync.com for customer invoice payments.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/client-support/pay-bill/",
        "quote": null
      }
    },
    {
      "product": "Web tracking, caching, and marketing scripts (googletagmanager.com, static.cloudflareinsights.com, cdn.leadinfo.net, link.msgsndr.com, to.getnitropack.com)",
      "purpose": "Website tag management, analytics, lead tracking, and page optimization",
      "evidence": {
        "statement": "The homepage loads scripts or frames from googletagmanager.com and static.cloudflareinsights.com and references cdn.leadinfo.net, link.msgsndr.com, and to.getnitropack.com.",
        "label": "inference",
        "sourceUrl": "https://www.tvit.net/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The New Client Onboarding Form collects sensitive infrastructure credentials, including server admin, local computer admin, and networking equipment passwords, via a standard web POST form.",
      "label": "fact",
      "sourceUrl": "https://www.tvit.net/client-support/client-onboarding-form/",
      "quote": "Server Admin Accounts and Passwords? Local Computer Admin Accounts and Passwords? Networking Equipment Account Name and Passwords?"
    },
    {
      "statement": "The homepage counter for 'Tickets Resolved Last Month' displays 0.",
      "label": "fact",
      "sourceUrl": "https://www.tvit.net/",
      "quote": "Tickets Resolved Last Month 0"
    }
  ],
  "problems": [
    {
      "problem": "Collecting plain-text administrative passwords on a general web onboarding form may create credential-handling overhead and security exposure compared to a dedicated vault or PSA onboarding workflow.",
      "label": "hypothesis",
      "basis": "The onboarding page asks new clients to type server, local admin, and network passwords directly into form fields."
    },
    {
      "problem": "The homepage counter showing 'Tickets Resolved Last Month 0' appears to be an unmaintained or broken website counter widget.",
      "label": "inference",
      "basis": "Observed directly on https://www.tvit.net/ where the counter value reads 0."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Existing IT client portal and PSA/documentation stack (tvit.itclientportal.com) and Microsoft 365 toolset",
      "addresses": "Structured client onboarding, credential documentation, and ticket management",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "Treasure Valley IT is a Managed IT Service Provider outside ForgeX's target segment of owner-led home-service contractors (HVAC, plumbing, and electrical), so no ForgeX solution is recommended."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because the company is outside ForgeX's target market and operates as an IT services provider."
  },
  "humanReview": [
    "No ForgeX automation is recommended; if the founder reviews this account, no outreach should be sent."
  ],
  "risks": [
    {
      "type": "security",
      "description": "Requesting server, computer, and network administrator passwords via a web form on https://www.tvit.net/client-support/client-onboarding-form/ carries credential-storage and transmission risks if not routed directly into an encrypted password manager."
    },
    {
      "type": "operational",
      "description": "Pursuing an IT managed service provider falls outside ForgeX's home-service contractor specialization and standardized field-service integrations."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website does not publish service pricing, and the company is not a fit for ForgeX's catalog."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Founder",
      "President / Managing Partner",
      "Operations or Service Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.tvit.net/"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.tvit.net/",
        "usedFor": "Business identity, Boise office address, service areas, vendor list, ticket counter, and sales phone channel"
      },
      {
        "url": "https://www.tvit.net/about/",
        "usedFor": "Company mission and Idaho Veterans Chamber of Commerce membership"
      },
      {
        "url": "https://www.tvit.net/meet-our-team-treasure-valley-it/",
        "usedFor": "Checked for named owners, executives, or managers (none listed on page)"
      },
      {
        "url": "https://www.tvit.net/our-services/",
        "usedFor": "Verification of core business activities as an IT managed services provider"
      },
      {
        "url": "https://www.tvit.net/software-and-productivity-services/",
        "usedFor": "Verification of Microsoft and Apple certified support and IT service offerings"
      },
      {
        "url": "https://www.tvit.net/privacy-policy/",
        "usedFor": "Verification of Google Ads and Gravatar usage"
      },
      {
        "url": "https://www.tvit.net/client-support/client-portal/",
        "usedFor": "Identification of client portal host (tvit.itclientportal.com)"
      },
      {
        "url": "https://www.tvit.net/client-support/pay-bill/",
        "usedFor": "Identification of payment portal host (secure2.wise-sync.com) and credit card processing fee policy"
      },
      {
        "url": "https://www.tvit.net/client-support/client-onboarding-form/",
        "usedFor": "Analysis of client onboarding form fields and workflow"
      },
      {
        "url": "https://www.tvit.net/client-support/remote-support/",
        "usedFor": "Review of remote support and ticket submission workflow"
      }
    ],
    "limitations": [
      "https://www.tvit.net/contact-us/ refused automated access (HTTP 403) and could not be read.",
      "The Meet Our Team and About pages do not name any owners, executives, or managers.",
      "Employee headcount, revenue, and service pricing are not published on the pages read.",
      "State business-registration details are not published on the website."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Treasure Valley IT is a Managed IT Service Provider (MSP) offering IT infrastructure, cybersecurity, and software support services rather than an owner-led home-service contractor in HVAC, plumbing, or electrical. Additionally, as an IT services provider with its own technical staff and client portal systems, it falls outside ForgeX's target segment."
  }
}
